261→// GetSupportedHooks returns the normalized lifecycle events this agent supports.
262→// Note: HookNames() returns 8 hooks but GetSupportedHooks() returns only 6.
263→// The two not listed here are:
264→//   - subagentStop: handled by ParseHookEvent (returns SubagentEnd), but there is no
265→//     HookType constant for subagent events (they use EventType instead).
266→//   - errorOccurred: pass-through hook with no lifecycle action (ParseHookEvent returns nil).
267→func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
268→	return []agent.HookType{
269→		agent.HookSessionStart,
270→		agent.HookSessionEnd,
271→		agent.HookUserPromptSubmit,
272→		agent.HookStop,
273→		agent.HookPreToolUse,
274→		agent.HookPostToolUse,
275→	}
276→}
277→
278→// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
279→func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) error {
280→	if data, ok := rawHooks[hookType]; ok {
281→		if err := json.Unmarshal(data, target); err != nil {
282→			return fmt.Errorf("invalid JSON for hook type %s: %w", hookType, err)
283→		}
284→	}
285→	return nil
286→}
287→
288→// marshalCopilotHookType marshals a hook type back into rawHooks.
289→// If the slice is empty, removes the key from rawHooks.
290→func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) error {
291→	if len(entries) == 0 {
292→		delete(rawHooks, hookType)
293→		return nil
294→	}
295→	data, err := json.Marshal(entries)
296→	if err != nil {
297→		return fmt.Errorf("failed to marshal hook type %s: %w", hookType, err)
298→	}
299→	rawHooks[hookType] = data
300→	return nil
301→}
302→
303→// hookBashExists checks if a hook with the given bash command already exists.
304→func hookBashExists(entries []CopilotHookEntry, bash string) bool {
305→	for _, entry := range entries {
306→		if entry.Bash == bash {
307→			return true
308→		}
309→	}
310→	return false
311→}
312→
313→// isEntireHook checks if a hook entry's bash command belongs to Entire.
314→func isEntireHook(bash string) bool {
315→	for _, prefix := range entireHookPrefixes {
316→		if strings.HasPrefix(bash, prefix) {
317→			return true
318→		}
319→	}
320→	return false
321→}
322→
323→// hasEntireHook checks if any entry in the slice is an Entire hook.
324→func hasEntireHook(entries []CopilotHookEntry) bool {
325→	for _, entry := range entries {
326→		if isEntireHook(entry.Bash) {
327→			return true
328→		}
329→	}
330→	return false
331→}
332→
333→// removeEntireHooks removes all Entire hooks from the slice.
334→func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
335→	result := make([]CopilotHookEntry, 0, len(entries))
336→	for _, entry := range entries {
337→		if !isEntireHook(entry.Bash) {
338→			result = append(result, entry)
339→		}
340→	}
341→	return result
342→}
