 85→// ReadSession reads a session from Copilot CLI's storage (JSONL transcript file).
 86→func (c *CopilotCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 87→	if input.SessionRef == "" {
 88→		return nil, errors.New("session reference (transcript path) is required")
 89→	}
 90→
 91→	data, err := os.ReadFile(input.SessionRef)
 92→	if err != nil {
 93→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 94→	}
 95→
 96→	// Parse events for ModifiedFiles; non-fatal if parsing fails since NativeData
 97→	// is the authoritative session content. ReadSession has no context.Context so
 98→	// we cannot log here — scanner errors are surfaced by other code paths that
 99→	// do have context (e.g. ExtractModifiedFilesFromOffset, ExtractPrompts).
100→	events, _ := parseEventsFromBytes(data) //nolint:errcheck // best-effort extraction
101→	var modifiedFiles []string
102→	if len(events) > 0 {
103→		modifiedFiles = extractModifiedFilesFromEvents(events)
104→	}
105→
106→	return &agent.AgentSession{
107→		SessionID:     input.SessionID,
108→		AgentName:     c.Name(),
109→		SessionRef:    input.SessionRef,
110→		StartTime:     time.Now(),
111→		NativeData:    data,
112→		ModifiedFiles: modifiedFiles,
113→	}, nil
114→}
115→
116→// WriteSession writes a session to Copilot CLI's storage (JSONL transcript file).
117→func (c *CopilotCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
118→	if session == nil {
119→		return errors.New("session is nil")
120→	}
121→
122→	if session.AgentName != "" && session.AgentName != c.Name() {
123→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
124→	}
125→
126→	if session.SessionRef == "" {
127→		return errors.New("session reference (transcript path) is required")
128→	}
129→
130→	if len(session.NativeData) == 0 {
131→		return errors.New("session has no native data to write")
132→	}
133→
134→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
135→		return fmt.Errorf("failed to write transcript: %w", err)
136→	}
137→
138→	return nil
139→}
