146→// ReadTranscript reads the raw JSONL transcript bytes for a session.
147→func (c *CopilotCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
148→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
149→	if err != nil {
150→		return nil, fmt.Errorf("failed to read transcript: %w", err)
151→	}
152→	return data, nil
153→}
154→
155→// ChunkTranscript splits a JSONL transcript at line boundaries.
156→func (c *CopilotCLIAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
157→	chunks, err := agent.ChunkJSONL(content, maxSize)
158→	if err != nil {
159→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
160→	}
161→	return chunks, nil
162→}
163→
164→// ReassembleTranscript concatenates JSONL chunks with newlines.
165→func (c *CopilotCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
166→	return agent.ReassembleJSONL(chunks), nil
167→}
