  1→package agents
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"os"
  8→	"os/exec"
  9→	"strings"
 10→	"syscall"
 11→	"time"
 12→)
 13→
 14→func init() {
 15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "copilot-cli" {
 16→		return
 17→	}
 18→	Register(&CopilotCLI{})
 19→	RegisterGate("copilot-cli", 4)
 20→}
