 60→func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 61→	cfg := &runConfig{Model: "gpt-4.1"}
 62→	for _, o := range opts {
 63→		o(cfg)
 64→	}
 65→
 66→	timeout := 60 * time.Second
 67→	if cfg.PromptTimeout > 0 {
 68→		timeout = cfg.PromptTimeout
 69→	}
 70→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
 71→	defer cancel()
 72→
 73→	args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
 74→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
 75→	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
 76→	cmd.Dir = dir
 77→	cmd.Stdin = nil
 78→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 79→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 80→	cmd.Cancel = func() error {
 81→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 82→	}
 83→	cmd.WaitDelay = 5 * time.Second
 84→
 85→	var stdout, stderr strings.Builder
 86→	cmd.Stdout = &stdout
 87→	cmd.Stderr = &stderr
 88→
 89→	err := cmd.Run()
 90→	exitCode := 0
 91→	if err != nil {
 92→		exitErr := &exec.ExitError{}
 93→		if errors.As(err, &exitErr) {
 94→			exitCode = exitErr.ExitCode()
 95→		} else {
 96→			exitCode = -1
 97→		}
 98→		if promptCtx.Err() == context.DeadlineExceeded {
 99→			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
100→		}
101→	}
102→
103→	out := Output{
104→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
105→		Stdout:   stdout.String(),
106→		Stderr:   stderr.String(),
107→		ExitCode: exitCode,
108→	}
109→
110→	// gpt-4.1 sometimes calls Copilot's Edit tool without required parameters,
111→	// producing zero code changes despite exit 0. Surface this as an error so
112→	// the transient-error retry mechanism can restart the scenario.
113→	// Only trigger when copilot reports zero changes — it may retry internally.
114→	if err == nil && strings.Contains(out.Stdout, "old_str is required") &&
115→		strings.Contains(out.Stderr, "Total code changes:     +0 -0") {
116→		err = errors.New("copilot Edit tool failed: old_str is required")
117→	}
118→
119→	return out, err
120→}
121→
122→func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
123→	bin, err := exec.LookPath(c.Binary())
124→	if err != nil {
125→		return nil, fmt.Errorf("agent binary not found: %w", err)
126→	}
127→
128→	// Forward critical env vars into the tmux session. tmux starts a new
129→	// shell that doesn't inherit Go's os.Environ(), so without this the
130→	// session lacks auth tokens (COPILOT_GITHUB_TOKEN) and HOME (for gh auth).
131→	if os.Getenv("COPILOT_GITHUB_TOKEN") == "" {
132→		return nil, errors.New("COPILOT_GITHUB_TOKEN is not set; copilot-cli interactive session requires authentication")
133→	}
134→	var envArgs []string
135→	for _, key := range []string{"COPILOT_GITHUB_TOKEN", "HOME", "TERM"} {
136→		if v := os.Getenv(key); v != "" {
137→			envArgs = append(envArgs, key+"="+v)
138→		}
139→	}
140→	args := append([]string{"env"}, envArgs...)
141→	args = append(args, bin, "--model", "gpt-4.1", "--allow-all")
142→
143→	name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
144→	// Strip CI env vars that may affect interactive mode.
145→	unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
146→	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
147→	if err != nil {
148→		return nil, err
149→	}
150→
151→	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
152→	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
153→	// new directories. "Yes" is pre-selected, so Enter dismisses it.
154→	foundPrompt := false
155→	for range 5 {
156→		content, err := s.WaitFor(`(❯|Enter to select)`, 30*time.Second)
157→		if err != nil {
158→			_ = s.Close()
159→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
160→		}
161→		if strings.Contains(content, "❯") && !strings.Contains(content, "Enter to select") {
162→			foundPrompt = true
163→			break
164→		}
165→		if err := s.SendKeys("Enter"); err != nil {
166→			_ = s.Close()
167→			return nil, fmt.Errorf("dismissing startup dialog: %w", err)
168→		}
169→		time.Sleep(500 * time.Millisecond)
170→	}
171→	if !foundPrompt {
172→		_ = s.Close()
173→		return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
174→	}
175→	s.stableAtSend = ""
176→
177→	return s, nil
178→}
