115→
116→	installedNames := GetAgentsWithHooksInstalled(ctx)
117→
118→	// Show currently installed agents
119→	if len(installedNames) > 0 {
120→		displayNames := make([]string, 0, len(installedNames))
121→		for _, name := range installedNames {
122→			if ag, err := agent.Get(name); err == nil {
123→				displayNames = append(displayNames, string(ag.Type()))
124→			}
125→		}
126→		fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(displayNames, ", "))
127→	}
