235→	}
236→
237→	if len(newAgents) == 0 {
238→		fmt.Fprintln(w, "No new agents selected.")
239→		return nil
240→	}
241→
242→	// Install hooks for newly selected agents only
243→	for _, ag := range newAgents {
244→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
245→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
246→		}
247→	}
248→
249→	newTypes := make([]string, 0, len(newAgents))
250→	for _, ag := range newAgents {
251→		newTypes = append(newTypes, string(ag.Type()))
252→	}
253→	fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(newTypes, ", "))
254→
255→	return nil
256→}
