258→func newSetupCmd() *cobra.Command {
259→	var opts EnableOptions
260→	var agentName string
261→	var removeAgentName string
262→
263→	cmd := &cobra.Command{
264→		Use:   "configure",
265→		Short: "Configure Entire in current repository",
266→		Long: `Configure Entire with session tracking for your AI agent workflows.
267→
268→On first run, this configures Entire and installs agent hooks.
269→On subsequent runs, it lets you enable more agents.
270→
271→Use --remove to remove a specific agent's hooks:
272→  entire configure --remove claude-code`,
273→		RunE: func(cmd *cobra.Command, _ []string) error {
274→			ctx := cmd.Context()
275→			if _, err := paths.WorktreeRoot(ctx); err != nil {
276→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire configure' from within a git repository.")
277→				return NewSilentError(errors.New("not a git repository"))
278→			}
279→
280→			// Discover external agent plugins early so they're available
281→			// for --agent, --remove, and interactive selection.
282→			external.DiscoverAndRegister(ctx)
283→
284→			// Remove agent mode
285→			if removeAgentName != "" {
286→				return runRemoveAgent(ctx, cmd.OutOrStdout(), removeAgentName)
287→			}
288→
289→			// Non-interactive --agent mode
290→			if cmd.Flags().Changed(agentFlagName) && agentName == "" {
291→				printMissingAgentError(cmd.ErrOrStderr())
292→				return NewSilentError(errors.New("missing agent name"))
293→			}
294→			if agentName != "" {
295→				ag, err := agent.Get(types.AgentName(agentName))
296→				if err != nil {
297→					printWrongAgentError(cmd.ErrOrStderr(), agentName)
298→					return NewSilentError(errors.New("wrong agent name"))
299→				}

