111→// findAgentDir returns the absolute path to cmd/entire/cli/agent/.
112→// Go test runner sets cwd to the package directory, so os.Getwd() gives us
113→// the agent dir directly.
114→func findAgentDir(t *testing.T) string {
115→	t.Helper()
116→	wd, err := os.Getwd()
117→	if err != nil {
118→		t.Fatalf("os.Getwd: %v", err)
119→	}
120→	return wd
121→}
122→
123→// discoverAgentPackages finds all subdirectories of the agent dir that contain
124→// Go files, excluding "types" and "testutil" (those are contract/shared packages).
125→func discoverAgentPackages(t *testing.T, agentDir string) []string {
126→	t.Helper()
127→
128→	skipDirs := map[string]bool{
129→		"types":    true, // contract types, not an agent implementation
130→		"testutil": true, // shared test utilities
131→		"external": true, // external agent adapter, not a self-registering agent
132→	}
133→
134→	entries, err := os.ReadDir(agentDir)
135→	if err != nil {
136→		t.Fatalf("ReadDir(%s): %v", agentDir, err)
137→	}
138→
139→	var pkgs []string
140→	for _, e := range entries {
141→		if !e.IsDir() || skipDirs[e.Name()] {
142→			continue
143→		}
144→		dir := filepath.Join(agentDir, e.Name())
145→		// Only include if it has Go files
146→		goFiles, err := filepath.Glob(filepath.Join(dir, "*.go"))
147→		if err != nil {
148→			t.Fatalf("filepath.Glob(%s): %v", dir, err)
149→		}
150→		if len(goFiles) > 0 {
151→			pkgs = append(pkgs, dir)
152→		}
153→	}
154→	return pkgs
155→}
156→
157→// extractImports parses all Go files in a directory and returns unique import paths.
158→// Includes both production and test files — test-only imports should also respect boundaries.
159→func extractImports(t *testing.T, dir string) []string {
160→	t.Helper()
161→
162→	fset := token.NewFileSet()
163→	//nolint:staticcheck // ParseDir is deprecated in favor of go/packages, but we intentionally
164→	// scan all files regardless of build tags to catch forbidden imports in test files too.
165→	pkgs, err := parser.ParseDir(fset, dir, nil, parser.ImportsOnly)
166→	if err != nil {
167→		t.Fatalf("parser.ParseDir(%s): %v", dir, err)
168→	}
169→
170→	seen := make(map[string]bool)
171→	for _, pkg := range pkgs {
172→		for _, file := range pkg.Files {
173→			for _, imp := range file.Imports {
174→				path, err := strconv.Unquote(imp.Path.Value)
175→				if err != nil {
176→					t.Fatalf("strconv.Unquote(%s): %v", imp.Path.Value, err)
177→				}
178→				seen[path] = true
179→			}
180→		}
181→	}
182→
183→	imports := make([]string, 0, len(seen))
184→	for imp := range seen {
185→		imports = append(imports, imp)
186→	}
187→	return imports
188→}
