190→// TestAgentPackages_SelfRegister verifies that each agent package has an init()
191→// function that calls agent.Register(). This ensures agents are properly
192→// discoverable via the registry.
193→func TestAgentPackages_SelfRegister(t *testing.T) {
194→	t.Parallel()
195→
196→	agentDir := findAgentDir(t)
197→	agentPkgs := discoverAgentPackages(t, agentDir)
198→
199→	if len(agentPkgs) == 0 {
200→		t.Fatal("no agent packages found — test setup is broken")
201→	}
202→
203→	for _, pkgDir := range agentPkgs {
204→		pkgName := filepath.Base(pkgDir)
205→		t.Run(pkgName, func(t *testing.T) {
206→			t.Parallel()
207→			if !hasInitWithRegister(t, pkgDir) {
208→				t.Errorf("agent package %q has no init() function calling Register() — agents must self-register", pkgName)
209→			}
210→		})
211→	}
212→}
213→
214→// hasInitWithRegister checks if any Go file in the directory has an init()
215→// function that contains a call to Register.
216→func hasInitWithRegister(t *testing.T, dir string) bool {
217→	t.Helper()
218→
219→	fset := token.NewFileSet()
220→	//nolint:staticcheck // See extractImports for rationale.
221→	pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool {
222→		return !strings.HasSuffix(fi.Name(), "_test.go")
223→	}, 0)
224→	if err != nil {
225→		t.Fatalf("parser.ParseDir(%s): %v", dir, err)
226→	}
227→
228→	for _, pkg := range pkgs {
229→		for _, file := range pkg.Files {
230→			for _, decl := range file.Decls {
231→				fn, ok := decl.(*ast.FuncDecl)
232→				if !ok || fn.Name.Name != "init" || fn.Recv != nil {
233→					continue
234→				}
235→				// Walk the init body looking for a call to Register or agent.Register
236→				found := false
237→				ast.Inspect(fn.Body, func(n ast.Node) bool {
238→					call, ok := n.(*ast.CallExpr)
239→					if !ok {
240→						return true
241→					}
242→					switch fun := call.Fun.(type) {
243→					case *ast.Ident:
244→						if fun.Name == "Register" {
245→							found = true
246→						}
247→					case *ast.SelectorExpr:
248→						if fun.Sel.Name == "Register" {
249→							found = true
250→						}
251→					}
252→					return !found
253→				})
254→				if found {
255→					return true
256→				}
257→			}
258→		}
259→	}
260→	return false
261→}
