// logSessionStateDiagnostic checks for session state files in .git/entire-sessions/
// and logs whether hooks fired. Also checks for shadow branches as a secondary signal.
func (s *RepoState) logSessionStateDiagnostic() {
	stateDir := filepath.Join(s.Dir, ".git", "entire-sessions")
	entries, err := os.ReadDir(stateDir)
	if err != nil {
		fmt.Fprintf(s.ConsoleLog, "> [diagnostic] no session state dir (%s) — agent hooks likely did not fire\n", stateDir)
		return
	}
	var sessionFiles []string
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".json") {
			sessionFiles = append(sessionFiles, e.Name())
		}
	}
	if len(sessionFiles) == 0 {
		fmt.Fprintf(s.ConsoleLog, "> [diagnostic] session state dir exists but empty — agent hooks likely did not fire\n")
	} else {
		fmt.Fprintf(s.ConsoleLog, "> [diagnostic] session state files: %s\n", strings.Join(sessionFiles, ", "))
	}

	// Check for shadow branches as a secondary signal (created by SaveStep on TurnEnd)
	branches := gitOutputSafe(s.Dir, "for-each-ref", "--format=%(refname:short)", "refs/heads/entire/")
	if branches != "" {
		fmt.Fprintf(s.ConsoleLog, "> [diagnostic] shadow branches: %s\n", strings.ReplaceAll(branches, "\n", ", "))
	} else {
		fmt.Fprintf(s.ConsoleLog, "> [diagnostic] no shadow branches — TurnEnd hook likely did not fire\n")
	}
}

