// AgentVersion runs `<binary> --version` and returns the trimmed first line,
// or "unknown" if the command fails. Safe to call during preflight — no
// network calls, just a local binary invocation.
func AgentVersion(a Agent) string {
	out, err := exec.Command(a.Binary(), "--version").Output()
	if err != nil {
		return "unknown"
	}
	v := strings.TrimSpace(string(out))
	// Some agents print multi-line version info; take the first line.
	if i := strings.IndexByte(v, '\n'); i >= 0 {
		v = v[:i]
	}
	return v
}

